function UploadCard({
  kind,
  state,
  disabled,
  onFile,
  onSheet,
}: {
  kind: MainKind;
  state?: FileState;
  disabled: boolean;
  onFile: (file: File) => void;
  onSheet: (sheet: string) => void;
}) {
  const ref = useRef<HTMLInputElement>(null);
  const [drag, setDrag] = useState(false);
  function drop(e: DragEvent) {
