  ST: ['payment_date', 'gross_cents'],
  QBO: ['posting_date', 'account_full_name', 'debit_cents', 'credit_cents'],
  QBD: ['posting_date', 'account_full_name', 'debit_cents', 'credit_cents'],
  BANK: ['posted_date', 'signed_cents'],
