  role: "CLEARING_RECEIPT" | "CLEARING_SETTLEMENT" | "FEE" | "BANK" | "OTHER" | "UNKNOWN";
  line_grain: "POSTING_LINE" | "TRANSACTION_SUMMARY";
  linked_payment_id: string | null;
  linked_deposit_id: string | null;
  accounting_batch_id: string | null;
